contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID) public payable {
        require(amount > 0 && loanToCollateral > 0, "params");

        c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;

        c.rescindRequest(reqID); if (__ESBMC_reverted()) return;

        bool reverted;
        c.rescindRequest(reqID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool active = c.isActive(reqID); if (__ESBMC_reverted()) return;

        assert(!active);
    }

    receive() external payable {}
}

