pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID) internal {
        vm.assume(amount > 0 && loanToCollateral > 0);
        try c.requestLoan(amount, interest, loanToCollateral, duration) {} catch { return; }
        try c.rescindRequest(reqID) {} catch { return; }
        bool reverted;
        try c.rescindRequest(reqID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool active;
        try c.isActive(reqID) returns (bool __r) { active = __r; } catch { return; }
        assertTrue(!active);
    }

    function testFuzz_run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID) public {
        _run(amount, interest, loanToCollateral, duration, reqID);
    }

    receive() external payable {}
}
